package org.KillerYT.regionMC.managers;

import org.KillerYT.regionMC.RegionMC;
import org.KillerYT.regionMC.region.Region;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.block.EnderChest;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockIgniteEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.entity.EntityPickupItemEvent;
import org.bukkit.event.entity.ExplosionPrimeEvent;
import org.bukkit.event.inventory.InventoryOpenEvent;
import org.bukkit.event.player.PlayerBedEnterEvent;
import org.bukkit.event.player.PlayerCommandPreprocessEvent;
import org.bukkit.event.player.PlayerDropItemEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.event.world.TimeSkipEvent;

import java.util.List;
import java.util.stream.Collectors;

public class RegionProtection implements Listener {

    private final RegionMC plugin;
    private final RegionManager regionManager;
    private final boolean debug;

    // Список команд RegionMC, которые никогда не должны блокироваться
    private final List<String> ALLOWED_REGIONMC_COMMANDS = List.of(
            "regionmc", "rg", "region",
            "regionmc:", "rg:", "region:",
            "regionmc.", "rg.", "region."
    );

    public RegionProtection(RegionMC plugin) {
        this.plugin = plugin;
        this.regionManager = plugin.getRegionManager();
        this.debug = plugin.getConfig().getBoolean("settings.debug", false);
    }

    // ========== НОВЫЙ ОБРАБОТЧИК ДЛЯ БЛОКИРОВКИ КОМАНД ==========

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onPlayerCommand(PlayerCommandPreprocessEvent event) {
        Player player = event.getPlayer();
        String command = event.getMessage().toLowerCase().trim();
        Location location = player.getLocation();

        // Проверяем, является ли команда командой RegionMC
        if (isRegionMCCommand(command)) {
            return; // Пропускаем команды RegionMC
        }

        // Получаем регион, в котором находится игрок
        String regionName = regionManager.findRegionAtLocation(location);

        if (regionName != null) {
            if (shouldBypassRegionProtection(player, regionName)) {
                return;
            }

            // Получаем регион и проверяем флаг blockcmd
            Region region = regionManager.getRegion(regionName);
            if (region != null) {
                Object blockCmdFlag = region.getFlag("blockcmd");

                if (blockCmdFlag != null) {
                    // Получаем флаг из FlagManager для проверки
                    org.KillerYT.regionMC.flags.main.AbstractRegionFlag<?> flag =
                            plugin.getFlagManager().getFlag("blockcmd");

                    if (flag instanceof org.KillerYT.regionMC.flags.BlockCmdFlag) {
                        // Приводим значение флага к правильному типу
                        List<String> blockedCommandsList = convertFlagValue(blockCmdFlag);

                        // Проверяем, заблокирована ли команда
                        if (isCommandBlocked(command, blockedCommandsList)) {
                            event.setCancelled(true);
                            sendProtectionMessage(player, "protection.command", "&cВы не можете использовать команды здесь!");

                            if (debug) {
                                plugin.getLogger().info("Command blocked: " + command +
                                        " in region: " + regionName +
                                        " for player: " + player.getName());
                            }
                        }
                    } else {
                        // Резервная проверка для Boolean флага
                        if (blockCmdFlag instanceof Boolean boolValue && !boolValue) {
                            // Если blockcmd = false, блокируем все команды
                            event.setCancelled(true);
                            sendProtectionMessage(player, "protection.command", "&cВы не можете использовать команды здесь!");

                            if (debug) {
                                plugin.getLogger().info("All commands blocked in region: " +
                                        regionName + " for player: " + player.getName());
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Обработчик изменения времени командой
     */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
    public void onTimeSetCommand(PlayerCommandPreprocessEvent event) {
        Player player = event.getPlayer();
        String command = event.getMessage().toLowerCase().trim();

        // Проверяем команды изменения времени
        if (command.startsWith("/time set") || command.startsWith("/time add")) {
            Location location = player.getLocation();

            // Находим регион в котором находится игрок
            String regionName = regionManager.findRegionAtLocation(location);

            if (regionName != null) {
                Region region = regionManager.getRegion(regionName);
                if (region != null) {
                    Object timeLockFlag = region.getFlag("time-lock");

                    if (timeLockFlag != null) {
                        String flagValue = timeLockFlag.toString().toLowerCase();

                        // Если время заблокировано - отменяем команду
                        if (flagValue.equals("deny")) {
                            event.setCancelled(true);
                            player.sendMessage("§cВремя заблокировано в этом регионе!");
                            return;
                        }

                        // Если установлен конкретный режим (day/night)
                        if (flagValue.equals("day") || flagValue.equals("night")) {
                            event.setCancelled(true);
                            player.sendMessage("§cВремя зафиксировано на " +
                                    (flagValue.equals("day") ? "дне" : "ночи") + " в этом регионе!");
                        }
                    }
                }
            }
        }
    }

    /**
     * Обработчик естественного изменения времени (таймер мира)
     */
    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onTimeChange(TimeSkipEvent event) {
        World world = event.getWorld();

        // Пропускаем события, которые не являются естественным течением времени
        if (event.getSkipReason() != TimeSkipEvent.SkipReason.NATURAL) {
            return;
        }

        // Получаем все регионы которые влияют на мир
        for (Region region : regionManager.getAllRegions()) {
            if (region.getPos1() == null || region.getPos2() == null) continue;

            // Проверяем, что регион в том же мире
            if (region.getPos1().getWorld().equals(world)) {
                Object timeLockFlag = region.getFlag("time-lock");

                if (timeLockFlag != null) {
                    String flagValue = timeLockFlag.toString().toLowerCase();

                    if (flagValue.equals("deny")) {
                        // Время заблокировано - отменяем изменение
                        event.setCancelled(true);
                        return;
                    }

                    if (flagValue.equals("day") || flagValue.equals("night")) {
                        // Устанавливаем фиксированное время для региона
                        long targetTime = flagValue.equals("day") ? 6000L : 18000L;

                        // Проверяем, совпадает ли текущее время с целевым
                        long currentTime = world.getTime();

                        // Если время отличается - устанавливаем нужное
                        if ((currentTime % 24000) != targetTime) {
                            // Отменяем событие
                            event.setCancelled(true);

                            // Используем прямой вызов без планировщика
                            long newTime = world.getFullTime() - (currentTime % 24000) + targetTime;

                            // Проверяем, сильно ли отличается время
                            if (Math.abs(newTime - world.getFullTime()) > 100) {
                                // Устанавливаем время напрямую, обходя события
                                setWorldTimeDirectly(world, newTime);
                            }

                            if (debug) {
                                plugin.getLogger().info("Fixed time to " + flagValue +
                                        " in region: " + region.getName() +
                                        " world: " + world.getName());
                            }
                        } else {
                            // Если время уже правильное, все равно блокируем изменение
                            event.setCancelled(true);
                        }
                        return;
                    }
                }
            }
        }
    }

    /**
     * Устанавливает время мира напрямую, избегая событий
     */
    private void setWorldTimeDirectly(World world, long time) {
        java.lang.reflect.Field dayTimeField = findDayTimeField(world);
        if (dayTimeField != null) {
            try {
                Object worldServer = getWorldServer(world);
                if (worldServer != null) {
                    dayTimeField.setAccessible(true);
                    dayTimeField.setLong(worldServer, time);
                }
            } catch (Exception ignored) {
                // Если что-то пошло не так, используем стандартный метод
            }
        }

        // Также устанавливаем полное время через Bukkit API
        // с небольшой задержкой, чтобы избежать рекурсии
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (world.getFullTime() != time) {
                world.setFullTime(time);
            }
        }, 1L);
    }

    /**
     * Находит поле dayTime через рефлексию
     */
    private java.lang.reflect.Field findDayTimeField(World world) {
        try {
            String version = Bukkit.getServer().getClass().getPackage().getName().split("\\.")[3];
            Class<?> craftWorldClass = Class.forName("org.bukkit.craftbukkit." + version + ".CraftWorld");
            Object craftWorld = craftWorldClass.cast(world);
            java.lang.reflect.Method getHandleMethod = craftWorldClass.getMethod("getHandle");
            Object worldServer = getHandleMethod.invoke(craftWorld);

            for (java.lang.reflect.Field field : worldServer.getClass().getDeclaredFields()) {
                if (field.getType() == long.class &&
                        (field.getName().contains("Time") || field.getName().contains("time"))) {
                    return field;
                }
            }
        } catch (Exception e) {
            return null;
        }
        return null;
    }

    /**
     * Получает WorldServer объект через рефлексию
     */
    private Object getWorldServer(World world) {
        try {
            String version = Bukkit.getServer().getClass().getPackage().getName().split("\\.")[3];
            Class<?> craftWorldClass = Class.forName("org.bukkit.craftbukkit." + version + ".CraftWorld");
            Object craftWorld = craftWorldClass.cast(world);
            java.lang.reflect.Method getHandleMethod = craftWorldClass.getMethod("getHandle");
            return getHandleMethod.invoke(craftWorld);
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Обработчик сна (игрок пытается проспать ночь)
     */
    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onPlayerBedEnter(PlayerBedEnterEvent event) {
        Player player = event.getPlayer();
        Location location = event.getBed().getLocation();

        String regionName = regionManager.findRegionAtLocation(location);

        if (regionName != null) {
            Region region = regionManager.getRegion(regionName);
            if (region != null) {
                Object timeLockFlag = region.getFlag("time-lock");

                if (timeLockFlag != null) {
                    String flagValue = timeLockFlag.toString().toLowerCase();

                    // Если время заблокировано или фиксировано - отменяем сон
                    if (flagValue.equals("deny") || flagValue.equals("day")) {
                        event.setCancelled(true);
                        player.sendMessage("§cВремя заблокировано в этом регионе, нельзя спать!");
                    }
                }
            }
        }
    }

    /**
     * Периодическая проверка времени (на всякий случай)
     */
    public void checkAndFixTime() {
        for (World world : Bukkit.getWorlds()) {
            // Проверяем только если в мире есть игроки
            if (world.getPlayers().isEmpty()) continue;

            for (Region region : regionManager.getAllRegions()) {
                if (region.getPos1() == null || region.getPos2() == null) continue;

                // Проверяем, что регион в этом мире
                if (!region.getPos1().getWorld().equals(world)) continue;

                Object timeLockFlag = region.getFlag("time-lock");

                if (timeLockFlag != null) {
                    String flagValue = timeLockFlag.toString().toLowerCase();

                    if (flagValue.equals("day") || flagValue.equals("night")) {
                        long targetTime = flagValue.equals("day") ? 6000L : 18000L;
                        long currentTime = world.getTime() % 24000;

                        // Если время отличается более чем на 100 тиков - фиксируем
                        if (Math.abs(currentTime - targetTime) > 100) {
                            // Используем прямой метод для установки времени
                            Bukkit.getScheduler().runTaskLater(plugin, () -> {
                                setWorldTimeDirectly(world, world.getFullTime() - currentTime + targetTime);
                            }, 1L);

                            if (plugin.getConfig().getBoolean("settings.debug", false)) {
                                plugin.getLogger().info("Fixed time to " + flagValue +
                                        " in region: " + region.getName() +
                                        " world: " + world.getName());
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Проверяет, является ли команда командой RegionMC
     */
    private boolean isRegionMCCommand(String command) {
        String normalizedCommand = normalizeCommand(command);

        for (String allowedCommand : ALLOWED_REGIONMC_COMMANDS) {
            String normalizedAllowed = normalizeCommand(allowedCommand);

            // Проверяем несколько вариантов:
            // 1. Точное совпадение
            if (normalizedCommand.equals(normalizedAllowed)) {
                return true;
            }

            // 2. Команда начинается с разрешенной команды
            if (normalizedCommand.startsWith(normalizedAllowed + " ")) {
                return true;
            }

            // 3. Команда содержит разрешенную команду как основную
            String[] commandParts = normalizedCommand.split("\\s+");
            if (commandParts.length > 0 && commandParts[0].equals(normalizedAllowed)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Проверяет, заблокирована ли команда
     */
    private boolean isCommandBlocked(String command, List<String> blockedCommandsList) {
        if (blockedCommandsList == null) {
            return false; // разрешить все команды
        } else if (blockedCommandsList.isEmpty()) {
            return true; // заблокировать все команды
        } else {
            String normalizedCommand = normalizeCommand(command);

            for (String blockedCommand : blockedCommandsList) {
                String normalizedBlocked = normalizeCommand(blockedCommand);

                // Проверяем несколько вариантов:
                // 1. Точное совпадение команды
                if (normalizedCommand.equals(normalizedBlocked)) {
                    return true;
                }

                // 2. Команда начинается с заблокированной (с пробелом)
                if (normalizedCommand.startsWith(normalizedBlocked + " ")) {
                    return true;
                }

                // 3. Команда содержит заблокированную подстроку (для случаев вроде /gmc, /gms, /gma)
                if (normalizedCommand.contains(normalizedBlocked)) {
                    // Но проверяем, что это не часть другого слова
                    String[] commandParts = normalizedCommand.split("\\s+");
                    for (String part : commandParts) {
                        if (part.equals(normalizedBlocked)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }
    }

    /**
     * Нормализует команду для сравнения
     */
    private String normalizeCommand(String command) {
        // Убираем слэш в начале если есть и приводим к нижнему регистру
        String normalized = command.toLowerCase().trim();
        if (normalized.startsWith("/")) {
            normalized = normalized.substring(1);
        }
        return normalized;
    }

    /**
     * Конвертирует значение флага в List<String> для BlockCmdFlag
     */
    @SuppressWarnings("unchecked")
    private List<String> convertFlagValue(Object flagValue) {
        if (flagValue == null) {
            return null; // разрешить все команды
        } else if (flagValue instanceof List) {
            return (List<String>) flagValue; // список заблокированных команд
        } else if (flagValue instanceof Boolean boolValue) {
            return boolValue ? null : List.of(); // true=разрешить все, false=заблокировать все
        } else if (flagValue instanceof String strValue) {
            // Обработка строковых значений с использованием switch
            String lowerValue = strValue.toLowerCase().trim();
            return switch (lowerValue) {
                case "true", "allow", "yes", "1", "разрешить" -> null; // разрешить все команды
                case "false", "deny", "no", "0", "запретить" -> List.of(); // заблокировать все команды
                default -> {
                    // Разделяем по запятым или пробелам и нормализуем команды
                    String[] commands = strValue.split("[,\\s]+");
                    List<String> result = new java.util.ArrayList<>();
                    for (String cmd : commands) {
                        if (!cmd.trim().isEmpty()) {
                            result.add(normalizeCommand(cmd.trim()));
                        }
                    }
                    yield result;
                }
            };
        }
        return null; // по умолчанию разрешить все
    }

    /**
     * Безопасная отправка сообщений защиты с fallback
     */
    private void sendProtectionMessage(Player player, String messageKey, String fallbackMessage) {
        try {
            String message = plugin.getLanguageManager().getMessage(messageKey);
            if (message == null || message.equals(messageKey) || message.contains("Message not found")) {
                // Если сообщение не найдено, используем fallback
                player.sendMessage(fallbackMessage);
            } else {
                player.sendMessage(message);
            }
        } catch (Exception e) {
            // В случае ошибки используем fallback
            player.sendMessage(fallbackMessage);
            if (debug) {
                plugin.getLogger().warning("Failed to send protection message for key: " + messageKey + ", using fallback");
            }
        }
    }

    // ========== ОСНОВНЫЕ ОБРАБОТЧИКИ ==========

    @EventHandler
    public void onBlockBreak(BlockBreakEvent event) {
        handleBuildEvent(event.getPlayer(), event.getBlock().getLocation(), event, "break");
    }

    @EventHandler
    public void onBlockPlace(BlockPlaceEvent event) {
        handleBuildEvent(event.getPlayer(), event.getBlock().getLocation(), event, "build");
    }

    /**
     * Общий метод для обработки событий строительства (разрушение и размещение блоков)
     */
    private void handleBuildEvent(Player player, Location location, Object event, String actionType) {
        String regionName = regionManager.findRegionAtLocation(location);

        if (regionName != null) {
            if (shouldBypassRegionProtection(player, regionName)) {
                return;
            }

            // Используем новый метод проверки из RegionManager
            boolean canBuild = switch (actionType) {
                case "break" -> regionManager.canBreakInRegion(player.getUniqueId(), regionName);
                case "place" -> regionManager.canPlaceInRegion(player.getUniqueId(), regionName);
                default -> regionManager.canBuildInRegion(player.getUniqueId(), regionName);
            };

            if (!canBuild) {
                if (event instanceof BlockBreakEvent breakEvent) {
                    breakEvent.setCancelled(true);
                } else if (event instanceof BlockPlaceEvent placeEvent) {
                    placeEvent.setCancelled(true);
                }

                // Разные сообщения для разных действий
                String messageKey;
                String fallbackMessage;

                if ("break".equals(actionType)) {
                    messageKey = "protection.break";
                    fallbackMessage = "&cВы не можете ломать блоки здесь!";
                } else if ("place".equals(actionType)) {
                    messageKey = "protection.place";
                    fallbackMessage = "&cВы не можете размещать блоки здесь!";
                } else {
                    messageKey = "protection.build";
                    fallbackMessage = "&cВы не можете строить здесь!";
                }

                sendProtectionMessage(player, messageKey, fallbackMessage);
            } else if (debug) {
                debugPermissions(player, regionName, actionType);
            }
        }
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onPlayerInteract(PlayerInteractEvent event) {
        Player player = event.getPlayer();

        if (event.getClickedBlock() == null) return;

        Location location = event.getClickedBlock().getLocation();
        String regionName = regionManager.findRegionAtLocation(location);

        if (regionName != null) {
            if (shouldBypassRegionProtection(player, regionName)) {
                return;
            }

            // Обработка эндерсундука - используем новый метод проверки
            if (event.getClickedBlock().getType() == Material.ENDER_CHEST && event.getAction() == Action.RIGHT_CLICK_BLOCK) {
                boolean canUseEnderChest = regionManager.canOpenEnderChestInRegion(player.getUniqueId(), regionName);
                if (!canUseEnderChest) {
                    event.setCancelled(true);
                    sendProtectionMessage(player, "protection.enderchest", "&cВы не можете использовать эндерсундуки здесь!");
                    return;
                }
            }

            // Для остальных взаимодействий используем обычную проверку
            if (!regionManager.canInteractInRegion(player.getUniqueId(), regionName)) {
                event.setCancelled(true);
                sendProtectionMessage(player, "protection.interact", "&cВы не можете взаимодействовать здесь!");
            }
        }
    }

    @EventHandler
    public void onEntityDamageByEntity(EntityDamageByEntityEvent event) {
        if (event.getDamager() instanceof Player damager && event.getEntity() instanceof Player target) {
            Location damagerLocation = damager.getLocation();
            Location targetLocation = target.getLocation();

            String damagerRegion = regionManager.findRegionAtLocation(damagerLocation);
            String targetRegion = regionManager.findRegionAtLocation(targetLocation);

            boolean bypassDamagerRegion = damagerRegion != null && shouldBypassRegionProtection(damager, damagerRegion);
            boolean bypassTargetRegion = targetRegion != null && shouldBypassRegionProtection(damager, targetRegion);

            if (bypassDamagerRegion || bypassTargetRegion) {
                return;
            }

            if (debug) {
                plugin.getLogger().info("=== DEBUG PvP PRIORITY ===");
                plugin.getLogger().info("Damager location region: " + damagerRegion);
                plugin.getLogger().info("Target location region: " + targetRegion);
                plugin.getLogger().info("Regions at damager: " + getRegionsAtLocation(damagerLocation));
                plugin.getLogger().info("Regions at target: " + getRegionsAtLocation(targetLocation));
                plugin.getLogger().info("=== END DEBUG ===");
            }

            // Используем правильный метод из RegionManager для PvP проверки
            boolean damagerPvPAllowed = damagerRegion == null || regionManager.canPvPInRegion(damagerRegion);
            boolean targetPvPAllowed = targetRegion == null || regionManager.canPvPInRegion(targetRegion);

            if (!damagerPvPAllowed || !targetPvPAllowed) {
                event.setCancelled(true);
                sendProtectionMessage(damager, "protection.pvp", "&cPvP отключен здесь!");
            }
        }
    }

    @EventHandler
    public void onPlayerMove(PlayerMoveEvent event) {
        Player player = event.getPlayer();
        Location to = event.getTo();
        Location from = event.getFrom();

        // Если координаты не изменились - пропускаем
        if (to.getBlockX() == from.getBlockX() &&
                to.getBlockY() == from.getBlockY() &&
                to.getBlockZ() == from.getBlockZ()) {
            return;
        }

        // Получаем регионы с учетом приоритета
        Region toRegion = regionManager.getRegionAtLocation(to);
        Region fromRegion = regionManager.getRegionAtLocation(from);

        // ДЕБАГ: Логируем информацию
        if (debug) {
            plugin.getLogger().info("Player " + player.getName() + " moving:");
            plugin.getLogger().info("  From region: " + (fromRegion != null ? fromRegion.getName() : "null"));
            plugin.getLogger().info("  To region: " + (toRegion != null ? toRegion.getName() : "null"));
        }

        // Проверка ВХОДА в регион
        if (toRegion != null && (fromRegion == null || !fromRegion.equals(toRegion))) {
            if (debug) {
                plugin.getLogger().info("  ENTERING region: " + toRegion.getName());
                Object entryFlag = toRegion.getFlag("entry");
                plugin.getLogger().info("  Entry flag value: " + entryFlag);
            }

            if (isDenied(player, toRegion, "entry")) {
                event.setCancelled(true);
                sendProtectionMessage(player, "protection.entry", "&cВы не можете войти в этот регион!");
                if (debug) {
                    plugin.getLogger().info("  ENTRY DENIED!");
                }
            } else if (debug) {
                plugin.getLogger().info("  ENTRY ALLOWED");
            }
        }

        // Проверка ВЫХОДА из региона
        if (fromRegion != null && (toRegion == null || !toRegion.equals(fromRegion))) {
            if (debug) {
                plugin.getLogger().info("  LEAVING region: " + fromRegion.getName());
                Object exitFlag = fromRegion.getFlag("exit");
                plugin.getLogger().info("  Exit flag value: " + exitFlag);
            }

            if (isDenied(player, fromRegion, "exit")) {
                event.setCancelled(true);
                sendProtectionMessage(player, "protection.exit", "&cВы не можете покинуть этот регион!");
                if (debug) {
                    plugin.getLogger().info("  EXIT DENIED!");
                }
            } else if (debug) {
                plugin.getLogger().info("  EXIT ALLOWED");
            }
        }
    }

    /**
     * Проверяет запрещено ли действие для игрока в регионе
     */
    private boolean isDenied(Player player, Region region, String flagName) {
        // Проверяем права владельца/участника
        if (regionManager.isOwner(player, region.getName()) || regionManager.isMember(player, region.getName())) {
            return false;
        }

        // Проверяем флаг
        Object flagValue = region.getFlag(flagName);
        org.KillerYT.regionMC.flags.main.AbstractRegionFlag<?> flag = plugin.getFlagManager().getFlag(flagName);

        if (flagValue != null && flag != null) {
            // Используем безопасное приведение типов через проверку класса
            try {
                // Для булевых флагов
                if (flagValue instanceof Boolean boolValue) {
                    return !boolValue;
                }
                // Для строковых флагов используем pattern variable
                else if (flagValue instanceof String strValue) {
                    String lowerValue = strValue.toLowerCase();
                    return switch (lowerValue) {
                        case "allow", "true", "yes", "1", "разрешить" -> false;
                        case "deny", "false", "no", "0", "запретить" -> true;
                        default -> true;
                    };
                }
                // Для других типов используем универсальный подход
                else {
                    // Создаем безопасную обертку для вызова isAllowed
                    return !isAllowedSafe(flag, flagValue);
                }
            } catch (ClassCastException e) {
                // Если типы не совпадают, используем значение по умолчанию
                return !isAllowedSafe(flag, flag.getDefaultValue());
            }
        }

        // Используем значение по умолчанию
        return flag == null || !isAllowedSafe(flag, flag.getDefaultValue());
    }

    /**
     * Безопасный вызов isAllowed с обработкой типов
     */
    @SuppressWarnings("unchecked")
    private <T> boolean isAllowedSafe(org.KillerYT.regionMC.flags.main.AbstractRegionFlag<T> flag, Object value) {
        try {
            // Пытаемся привести тип
            T typedValue = (T) value;
            return flag.isAllowed(typedValue);
        } catch (ClassCastException e) {
            // Если приведение не удалось, используем значение по умолчанию
            return flag.isAllowed(flag.getDefaultValue());
        }
    }

