    /**
     * Проверяет, может ли игрок обойти защиту регионов (общий байпас)
     */
    private boolean shouldBypassProtection(Player player) {
        return player.isOp() ||
                hasPermission(player, "regionmc.bypass") ||
                hasPermission(player, "regionmc.admin") ||
                hasPermission(player, "regionmc.command.region.bypass.*");
    }

    /**
     * Проверяет, может ли игрок обойти защиту конкретного региона
     */
    private boolean shouldBypassRegionProtection(Player player, String regionName) {
        if (shouldBypassProtection(player)) {
            return !hasPermission(player, "regionmc.command.region.bypass." + regionName + ".false");
        }

        return hasPermission(player, "regionmc.command.region.bypass." + regionName) &&
                !hasPermission(player, "regionmc.command.region.bypass." + regionName + ".false");
    }

    /**
     * Проверяет наличие прав с поддержкой групповых permissions
     */
    private boolean hasPermission(Player player, String permission) {
        if (player.hasPermission(permission) || player.isOp()) {
            return true;
        }

        return hasGroupPermission(player, permission);
    }

    /**
     * Проверяет групповые permissions из конфигурации
     */
    private boolean hasGroupPermission(Player player, String permission) {
        ConfigurationSection groups = plugin.getConfig().getConfigurationSection("permission-groups");
        if (groups == null) return false;

        for (String groupName : groups.getKeys(false)) {
            String mainPermission = groups.getString(groupName + ".main-permission");
            List<String> groupPermissions = groups.getStringList(groupName + ".permissions");

            if (mainPermission != null && player.hasPermission(mainPermission) && groupPermissions.contains(permission)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Получает значение флага для локации с учетом приоритета регионов
     */
    private boolean getEffectiveFlagValueForLocation(Location location, String flag) {
        List<Region> regionsAtLocation = regionManager.getRegionsAtLocation(location);

        for (Region region : regionsAtLocation) {
            Object flagValue = region.getFlag(flag);
            if (flagValue != null) {
                if (flagValue instanceof Boolean boolValue) {
                    return boolValue;
                } else if (flagValue instanceof String strValue) {
                    String lowerValue = strValue.toLowerCase();
                    return switch (lowerValue) {
                        case "allow", "true", "yes", "1", "разрешить" -> true;
                        case "deny", "false", "no", "0", "запретить" -> false;
                        default -> false;
                    };
                }
            }
        }

        return true;
    }

    /**
     * Вспомогательные методы для работы с флагами и регионами
     */
    private List<String> getRegionsAtLocation(Location location) {
        // Получаем список регионов и преобразуем в список имен
        List<Region> regions = regionManager.getRegionsAtLocation(location);
        return regions.stream()
                .map(Region::getName)
                .collect(Collectors.toList());
    }

    private int getRegionPriority(String regionName) {
        // Получаем регион и возвращаем его приоритет
        Region region = regionManager.getRegion(regionName);
        return region != null ? region.getPriority() : 0;
    }
